from z3 import *

def solve():
    V = 17
    E = [[Bool(f"e_{i}_{j}") if i < j else None for j in range(V)] for i in range(V)]

    def edge(i, j):
        if i < j: return E[i][j]
        if i > j: return E[j][i]
        return False

    s = Solver()

    # At least 28 edges
    s.add(Sum([If(E[i][j], 1, 0) for i in range(V) for j in range(i+1, V)]) >= 28)

    # Girth >= 6
    # No 3-cycles
    for i in range(V):
        for j in range(i+1, V):
            for k in range(j+1, V):
                s.add(Not(And(edge(i, j), edge(j, k), edge(k, i))))

    # No 4-cycles
    for i in range(V):
        for j in range(i+1, V):
            for k in range(j+1, V):
                for l in range(k+1, V):
                    # A 4-cycle on i, j, k, l can be formed in 3 ways:
                    # i-j-k-l-i
                    s.add(Not(And(edge(i, j), edge(j, k), edge(k, l), edge(l, i))))
                    # i-j-l-k-i
                    s.add(Not(And(edge(i, j), edge(j, l), edge(l, k), edge(k, i))))
                    # i-k-j-l-i
                    s.add(Not(And(edge(i, k), edge(k, j), edge(j, l), edge(l, i))))

    # No 5-cycles
    import itertools
    for p in itertools.combinations(range(V), 5):
        # For 5 vertices, there are 12 possible 5-cycles
        # We can just say: any permutation of 5 vertices cannot form a cycle
        # Actually, it's easier to just iterate over all permutations of 5 vertices, modulo cyclic shifts and reversals
        # Or just all permutations of p[1:] since p[0] can be fixed
        for perm in itertools.permutations(p[1:]):
            # Check if perm[0] < perm[-1] to avoid reversing
            if perm[0] < perm[-1]:
                cycle = [p[0]] + list(perm)
                s.add(Not(And(
                    edge(cycle[0], cycle[1]),
                    edge(cycle[1], cycle[2]),
                    edge(cycle[2], cycle[3]),
                    edge(cycle[3], cycle[4]),
                    edge(cycle[4], cycle[0])
                )))

    # 4-colorable
    C = [Int(f"c_{i}") for i in range(V)]
    for i in range(V):
        s.add(C[i] >= 0, C[i] <= 3)
    for i in range(V):
        for j in range(i+1, V):
            s.add(Implies(edge(i, j), C[i] != C[j]))

    print("Solving...")
    res = s.check()
    if res == sat:
        m = s.model()
        edges = []
        for i in range(V):
            for j in range(i+1, V):
                if is_true(m[E[i][j]]):
                    edges.append((i, j))
        print("SAT")
        print(edges)
    else:
        print(res)

solve()

